require __DIR__.'/app/bootstrap.php';$u=require_login();$id=(int)($_GET['id']??0);$i=operations_row('SELECT i.*,o.order_number FROM commerce_invoices i LEFT JOIN store_orders o ON o.id=i.order_id WHERE i.id=?',[$id]);if(!$i){http_response_code(404);exit('Invoice not found.');}$allowed=(int)$i['buyer_user_id']===(int)$u['id']||(int)$i['seller_user_id']===(int)$u['id']||can_access_admin_panel($u);if(!$allowed){http_response_code(403);exit('Access denied.');}$items=operations_rows('SELECT * FROM commerce_invoice_items WHERE invoice_id=? ORDER BY id',[$id]);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($i['invoice_number'])?></title><style>body{font-family:Arial;background:#f5f7fb;color:#172033;margin:0}.invoice{max-width:900px;margin:30px auto;background:#fff;padding:36px;border-radius:18px}.top{display:flex;justify-content:space-between;gap:20px}.brand{font-size:28px;font-weight:800}.muted{color:#64748b}table{width:100%;border-collapse:collapse;margin:25px 0}th,td{text-align:left;padding:12px;border-bottom:1px solid #e5e7eb}.totals{margin-left:auto;max-width:360px}.totals div{display:flex;justify-content:space-between;padding:7px}.actions{text-align:right;margin-bottom:20px}@media print{body{background:#fff}.invoice{margin:0;box-shadow:none}.actions{display:none}}</style></head><body><div class="invoice"><div class="actions"><button onclick="window.print()">Print / Save PDF</button></div><div class="top"><div><div class="brand"><?=e(setting('site_name','ShahkotPK'))?></div><div class="muted"><?=e(setting('business_address',''))?></div></div><div><b><?=e($i['invoice_number'])?></b><br><span class="muted">Issue <?=e($i['issue_date'])?><br>Order <?=e($i['order_number'])?><br>Status <?=e($i['status'])?></span></div></div><hr><p><b>Bill To</b><br><?=e($i['billing_name'])?><br><?=e($i['billing_phone'])?><br><?=e($i['billing_email'])?><br><?=e($i['billing_address'])?></p><table><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Total</th></tr><?php foreach($items as $x):?><tr><td><?=e($x['description'])?></td><td><?=e($x['quantity'])?></td><td>Rs <?=e(number_format((float)$x['unit_price'],2))?></td><td>Rs <?=e(number_format((float)$x['line_total'],2))?></td></tr><?php endforeach;?></table><div class="totals"><div><span>Subtotal</span><b>Rs <?=e(number_format((float)$i['subtotal'],2))?></b></div><div><span>Shipping</span><b>Rs <?=e(number_format((float)$i['shipping_amount'],2))?></b></div><div><span>Total</span><b>Rs <?=e(number_format((float)$i['total_amount'],2))?></b></div><div><span>Paid</span><b>Rs <?=e(number_format((float)$i['paid_amount'],2))?></b></div></div></div></body></html>
